PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE stores (
  id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, city TEXT, fb_url TEXT, ig_url TEXT);
CREATE TABLE items (
  id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, category TEXT, basis TEXT);
CREATE TABLE prices (
  id INTEGER PRIMARY KEY,
  item_id INTEGER NOT NULL REFERENCES items(id),
  store_id INTEGER NOT NULL REFERENCES stores(id),
  brand TEXT, note TEXT,
  price REAL NOT NULL, qty REAL NOT NULL DEFAULT 1, price_per_unit REAL NOT NULL,
  valid_from TEXT, valid_to TEXT, source TEXT, verified INTEGER NOT NULL DEFAULT 0,
  captured_on TEXT NOT NULL);
CREATE INDEX idx_prices_item ON prices(item_id);
CREATE INDEX idx_prices_store ON prices(store_id);
COMMIT;
